
import argparse
import csv
import time
from pathlib import Path

import serial

parser = argparse.ArgumentParser()
parser.add_argument("--port", default="COM5")
parser.add_argument("--active", action="store_true")
parser.add_argument("--strength", type=int, default=20)
parser.add_argument("--seconds", type=float, default=10)
args = parser.parse_args()

mode = "active" if args.active else "passive"
filename = Path(f"vc_{mode}_{args.strength}pct.csv")

# The diagnostic stream is generated by the firmware.
# Use the validated serial interface settings.
with serial.Serial(args.port, 500000, timeout=0.1,
                   write_timeout=1) as ser:

    def command(text):
        ser.write((text + "\n").encode("ascii"))
        ser.flush()
        time.sleep(0.15)

    # Allow USB/boot communications to settle.
    time.sleep(2)
    ser.reset_input_buffer()

    try:
        command("VCT 0")
        command("VCM 1")
        command("VCA 1" if args.active else "VCA 0")
        command("PC1 -70")

        # Fixed stimulus percentage.
        # Existing frequency/knob configuration is retained.
        command("SC0")
        command(f"ST1 {args.strength}")
        command("VCT 1")

        prefix = "VC2," if args.active else "VC1,"
        rows = []
        end_time = time.monotonic() + args.seconds

        while time.monotonic() < end_time:
            raw = ser.readline()
            line = raw.decode("ascii", errors="ignore").strip()

            if line.startswith(prefix):
                fields = line.split(",")

                # VC1: 12 columns; VC2: 18 columns.
                count = 18 if args.active else 12
                if len(fields) == count:
                    rows.append(fields)

        command("VCT 0")

        if not rows:
            raise RuntimeError(
                "No VC diagnostic rows received. "
                "Check COM port, firmware mode and USB settings."
            )

        # Preserve the original diagnostic column order.
        with filename.open("w", newline="") as file:
            writer = csv.writer(file)
            writer.writerows(rows)

        print(f"Saved {len(rows)} samples to {filename}")

        # Both VC1 and VC2 share these column positions.
        voltages = [float(r[4]) for r in rows]
        currents = [float(r[5]) for r in rows]
        commands = [float(r[3]) for r in rows]

        print(f"Vcmd range: {min(commands):.3f} "
              f"to {max(commands):.3f} mV")
        print(f"Vm range: {min(voltages):.3f} "
              f"to {max(voltages):.3f} mV")
        print(f"Clamp current range: {min(currents):.6f} "
              f"to {max(currents):.6f} nA")

    finally:
        # Return the board to ordinary telemetry and
        # hardware control, even if capture fails.
        command("VCT 0")
        command("ST0")
        command("PC0")
        command("VCM 0")
